const d = { ...$json };

// ── 基础工具 ──────────────────────────────────────────────

/** 归一化豆包输出的"是"/"否"/"不确定" */
function normalizeYesNo(value) {
  const v = String(value || '').trim();
  if (v === '是' || v === '否' || v === '不确定') return v;
  return '不确定';
}

/**
 * 聚合多页签章识别结果：存在即视为"是"
 * - 任意页出现"是" → 聚合结果为"是"
 * - 无"是"但有"不确定" → "不确定"
 * - 全部"否"或空 → "否"
 */
function aggregateField(pages, field) {
  let hasYes = false;
  let hasUncertain = false;
  for (const page of pages) {
    const val = normalizeYesNo(page[field]);
    if (val === '是') hasYes = true;
    else if (val === '不确定') hasUncertain = true;
  }
  if (hasYes) return '是';
  if (hasUncertain) return '不确定';
  return '否';
}

/** 由甲/乙方盖章推导双方盖章状态 */
function derive双方(甲方, 乙方) {
  if (甲方 === '是' && 乙方 === '是') return '是';
  if (甲方 === '否' || 乙方 === '否') return '否';
  return '不确定';
}

/**
 * 签字合同有效性判断
 * - 有甲方签字 + (甲方盖章=是 或 身份证复印件=是) → 有效
 * - 有甲方签字，但盖章和身份证都不是"是" → 无效签字合同
 */
function evaluateSignContract(甲方签字, 甲方身份证复印件, 甲方盖章) {
  if (甲方签字 === '是') {
    if (甲方盖章 === '是' || 甲方身份证复印件 === '是') {
      return '有效';
    }
    return '无效签字合同';
  }
  if (甲方签字 === '否') return '不适用';
  return '不确定';
}

/** 稳健地从可能是对象的值中提取字符串（用于交叉核验） */
function extractComparableString(val) {
  if (val === undefined || val === null) return '';
  if (typeof val === 'object') {
    if (Array.isArray(val)) return val.map(extractComparableString).join(',');
    return String(val.text ?? val.value ?? val.name ?? val.label ?? '');
  }
  return String(val).trim();
}

// ── 聚合所有签章页（替代单页优选） ──────────────────────

const pageDetails = Array.isArray(d.签章页识别明细) ? d.签章页识别明细 : [];

const 甲方 = aggregateField(pageDetails, '甲方盖章');
const 乙方 = aggregateField(pageDetails, '乙方盖章');
const 双方 = derive双方(甲方, 乙方);
const 甲方签字 = aggregateField(pageDetails, '甲方签字');
const 甲方身份证复印件 = aggregateField(pageDetails, '甲方身份证复印件');
const 签字合同状态 = evaluateSignContract(甲方签字, 甲方身份证复印件, 甲方);

// 生成各页说明（供展示用）
const stampDetailText = pageDetails.length
  ? pageDetails
      .map(
        (r) =>
          `第${r.page}页：甲方盖章${normalizeYesNo(r.甲方盖章)}，乙方盖章${normalizeYesNo(r.乙方盖章)}，甲方签字${normalizeYesNo(r.甲方签字)}，身份证${normalizeYesNo(r.甲方身份证复印件)}${r.说明 ? `（${r.说明}）` : ''}`
      )
      .join('；')
  : d.盖章说明 || '';

// ── 组装校验信息 ──────────────────────────────────────────

const lines = [
  '【合同校验】',
  d.execNo ? `执行编号：${d.execNo}` : '',
  `双方盖章：${双方}`,
  `甲方盖章：${甲方}`,
  `乙方盖章：${乙方}`,
  `甲方签字：${甲方签字}`,
  `甲方身份证复印件：${甲方身份证复印件}`,
  签字合同状态 && 签字合同状态 !== '不适用'
    ? `签字合同状态：${签字合同状态}`
    : '',
  `签章判定依据：综合全部签章页聚合判断`,
  `活动名称：${d.活动名称 || '-'}`,
  `活动日期：${d.活动日期 || '-'}`,
  `活动人数：${d.活动人数 || '-'}`,
  `活动总费用：${d.活动总费用 || '-'}`,
  `付款比例和方式：${d.付款比例和方式 || '-'}`,
];

if (d.字段识别说明) lines.push(`字段识别说明：${d.字段识别说明}`);
if (stampDetailText) lines.push(`盖章识别说明：${stampDetailText}`);

// 缺失字段收集
const missing = [
  !d.活动名称 ? '活动名称' : '',
  !d.活动日期 ? '活动日期' : '',
  !d.活动人数 ? '活动人数' : '',
  !d.活动总费用 ? '活动总费用' : '',
  !d.付款比例和方式 ? '付款比例和方式' : '',
].filter(Boolean);

// 交叉核验（从执行表获取字段，使用稳健提取方法）
const execCtx = $('02 检查订单合同').item?.json || {};

const refExecPeopleRaw = execCtx.订单执行人数 || execCtx.执行人数 || '';
const refExecDateRaw = execCtx.订单执行日期 || execCtx.执行日期 || '';
const refContractPriceRaw = execCtx.订单合同价款 || '';

const refExecPeople = extractComparableString(refExecPeopleRaw);
const refExecDate = extractComparableString(refExecDateRaw);
const refContractPrice = extractComparableString(refContractPriceRaw);

const crossIssues = [];
if (refExecPeople && d.活动人数 && refExecPeople !== String(d.活动人数)) {
  crossIssues.push(`活动人数(${d.活动人数})与执行人数(${refExecPeople})不一致`);
}
if (refExecDate && d.活动日期 && refExecDate !== String(d.活动日期)) {
  crossIssues.push(`活动日期(${d.活动日期})与执行日期(${refExecDate})不一致`);
}
if (refContractPrice && d.活动总费用 && refContractPrice !== String(d.活动总费用)) {
  crossIssues.push(`活动总费用(${d.活动总费用})与合同价款(${refContractPrice})不一致`);
}
if (crossIssues.length) {
  lines.push(`交叉核验：${crossIssues.join('；')}`);
}

// ── 合同识别状态判定（优化：盖章成功+字段缺失 → 新状态） ──

const isBothStamped = 双方 === '是';           // 双方盖章齐全
const hasSign = 甲方签字 === '是';
const isValidSignContract = 签字合同状态 === '有效';
const isInvalidSignContract = 签字合同状态 === '无效签字合同';
const isPdfOverSize = d.盖章说明 && d.盖章说明.includes('PDF超过10MB');

let recognizeStatus = '校验正确';

// 硬性异常：超大 PDF（即使盖章成功也先提示需人工复核）
if (isPdfOverSize) {
  recognizeStatus = '需人工复核';
}
// ★ 双方已盖章：最高优先级
else if (isBothStamped) {
  // 盖章校验成功，但存在内容字段缺失 → 单独状态
  if (missing.length > 0) {
    recognizeStatus = '签章正确⚠️内容识别失败';
  } else {
    recognizeStatus = '校验正确';
  }
}
// 盖章未通过，按原有逻辑处理
else if (missing.length >= 3) {
  recognizeStatus = '识别失败';
}
else if (甲方 === '否' && 乙方 === '否') {
  recognizeStatus = '双方未盖章';
} else if (甲方 === '否') {
  recognizeStatus = '甲方未盖章';
} else if (乙方 === '否') {
  recognizeStatus = '乙方未盖章';
} else if (双方 === '否') {
  recognizeStatus = '双方未盖章';
}
// 未双方盖章，但有甲方签字 → 评估签字合同有效性
else if (hasSign) {
  if (isInvalidSignContract) {
    recognizeStatus = '无效签字合同';
  } else if (isValidSignContract) {
    recognizeStatus = '校验正确';
  } else {
    recognizeStatus = '需人工复核';
  }
}
// 无双方盖章、无明确签字，但签字合同有效（历史数据）
else if (isValidSignContract) {
  recognizeStatus = '校验正确';
}
// 仍有不确定因素
else if (
  missing.length > 0 ||
  甲方 === '不确定' ||
  乙方 === '不确定' ||
  双方 === '不确定' ||
  签字合同状态 === '不确定'
) {
  recognizeStatus = '需人工复核';
}

const verifyInfo = lines.filter(Boolean).join('\n');

// 预付款比例校验：将上游可能为布尔/字符串的值转为统一状态
const rawPayWarning = d.付款比例是否预警;
let 预付款比例校验 = '失败';                              // 默认失败
if (rawPayWarning === true || rawPayWarning === '是' || String(rawPayWarning).toLowerCase() === 'true') {
  预付款比例校验 = '预警';
} else if (rawPayWarning === false || rawPayWarning === '否' || String(rawPayWarning).toLowerCase() === 'false') {
  预付款比例校验 = '正常';
}
// 其他情况（undefined/null/空字符串等）保持默认的“失败”

return {
  json: {
    ...d,
    recognizeStatus,
    合同识别状态: recognizeStatus,
    校验信息: verifyInfo,
    签章判定页: null,
    签章聚合结果: {
      甲方盖章: 甲方,
      乙方盖章: 乙方,
      双方盖章: 双方,
      甲方签字,
      甲方身份证复印件,
      预付款比例校验,
      签字合同状态,
    },
    feishu_ready: true,
    feishu_update_body: {
      fields: {
        合同识别状态: recognizeStatus,
        校验信息: verifyInfo,
        预付款比例校验
      },
    },
  },
};

const ctx = $('01 检查执行记录').item.json;
const parser = $json || {};
const pages = Array.isArray(parser.pages) ? parser.pages : [];
const pageText = pages
  .map((p) => `--- 第 ${p.page} 页 ---\n${p.text || ''}`)
  .join('\n\n');

return {
  json: {
    record_id: ctx.record_id,
    execNo: ctx.execNo,
    pages,
    pageText,
    pdf_page_count: parser.page_count || 0,
    pdf_selected_pages: parser.selected_pages || [],
    pdf_stamp_pages: parser.stamp_pages || [],
  },
};

const prep = $('准备合同文本').item.json;
const raw = $json.output ?? $json.text ?? $json.response ?? '';

let data = {};
try {
  const cleaned = String(raw).replace(/```json/g, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start >= 0 && end > start) {
    data = JSON.parse(cleaned.slice(start, end + 1));
  }
} catch (error) {
  data = { 说明: `DeepSeek 输出解析失败：${error.message || error}` };
}

return {
  json: {
    record_id: prep.record_id,
    execNo: prep.execNo,
    stamp_pages: prep.pdf_stamp_pages || prep.stamp_pages || [],
    活动名称: data['活动名称'] || data.活动名称 || '',
    活动日期: data['活动日期'] || data.活动日期 || '',
    活动人数: String(data['活动人数'] || data.活动人数 || ''),
    活动总费用: String(data['活动总费用'] || data.活动总费用 || ''),
    付款比例和方式: data['付款比例和方式'] || data.付款比例和方式 || '',
    付款比例是否预警: data['付款比例是否预警'] || data.付款比例是否预警 || '',
    字段识别说明: data['说明'] || data.说明 || '',
  },
};

const base = { ...$json };
const parser = $('调用合同解析服务').item?.json || {};
const stampImages = (parser.stamp_images || [])
  .filter((x) => x?.image_base64)
  .map((x) => ({
    page: x.page,
    image_base64: String(x.image_base64).replace(/\s/g, ''),
  }))
  .filter((x) => x.image_base64.length > 0);

if (!stampImages.length) {
  return [
    {
      json: {
        ...base,
        has_stamp_image: false,
        stamp_page: null,
        image_base64: '',
        skip_doubao: true,
        skip_doubao_reason: '未获取签章页图片',
      },
    },
  ];
}

return stampImages.map((img) => ({
  json: {
    ...base,
    has_stamp_image: true,
    stamp_page: img.page,
    image_base64: img.image_base64,
    skip_doubao: false,
  },
}));

const base = $('解析DeepSeek输出').first().json;
const prepItems = $('准备签章图片').all();
const doubaoItems = $input.all();

const defaults = {
  双方盖章: '不确定',
  甲方盖章: '不确定',
  乙方盖章: '不确定',
  甲方签字: '不确定',
  甲方身份证复印件: '不确定',
  签字合同状态: '不适用',
  盖章说明: '',
};

function hasDoubaoResponse(item) {
  const j = item?.json || {};
  return Array.isArray(j.output) || typeof j.output_text === 'string';
}

// 只有豆包完全没结果时才跳过（不要再用 checkCtx.skipDoubao 挡正常结果）
if (!doubaoItems.length || !doubaoItems.some(hasDoubaoResponse)) {
  const skipReason = prepItems[0]?.json?.skip_doubao_reason || '未获取签章页图片';
  return {
    json: {
      ...base,
      ...defaults,
      盖章说明: skipReason,
    },
  };
}

function extractText(res) {
  if (typeof res?.output_text === 'string' && res.output_text.trim()) {
    return res.output_text.trim();
  }

  const chunks = [];
  for (const item of res?.output || []) {
    if (item?.type === 'message' && Array.isArray(item.content)) {
      for (const part of item.content) {
        if (typeof part?.text === 'string' && part.text.trim()) {
          chunks.push(part.text.trim());
        }
      }
    }
    if (item?.type === 'reasoning' && Array.isArray(item.summary)) {
      for (const part of item.summary) {
        if (typeof part?.text === 'string' && part.text.trim()) {
          chunks.push(part.text.trim());
        }
      }
    }
  }
  return chunks.join('\n');
}

function parseStampJson(raw) {
  const cleaned = String(raw).replace(/```json/g, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(cleaned.slice(start, end + 1));
  } catch (_) {
    return null;
  }
}

function normalizeYesNo(value) {
  const v = String(value || '').trim();
  if (v === '是' || v === '否' || v === '不确定') return v;
  return '不确定';
}

function inferFromText(text) {
  const t = String(text || '');

  const result = {
    甲方盖章: '不确定',
    乙方盖章: '不确定',
    甲方签字: '不确定',
    甲方身份证复印件: '不确定',
    说明: '',
  };

  // 甲方盖章
  if (/甲方[^\\n|]{0,40}(?:已|有)[^\\n|]{0,20}(?:盖章|公章|鲜章)/.test(t)) {
    result.甲方盖章 = '是';
  } else if (/甲方[^\\n|]{0,40}(?:未|暂未|没有|无)[^\\n|]{0,20}(?:盖章|公章)/.test(t)) {
    result.甲方盖章 = '否';
  }

  // 乙方盖章
  if (/乙方[^\\n|]{0,40}(?:已|有)[^\\n|]{0,20}(?:盖章|公章|鲜章)/.test(t)) {
    result.乙方盖章 = '是';
  } else if (/乙方[^\\n|]{0,40}(?:未|暂未|没有|无)[^\\n|]{0,20}(?:盖章|公章)/.test(t)) {
    result.乙方盖章 = '否';
  }

  // 报价单页：整页公章
  if (result.乙方盖章 === '不确定' && /(?:报价单|含税总价)[\\s\\S]{0,200}(?:加盖|盖有)[^\\n]{0,30}(?:公章|鲜章)/.test(t)) {
    result.乙方盖章 = '是';
  }

  // 甲方签字
  if (/甲方[^\\n|]{0,40}(?:手写签名|签字)/.test(t) || /签字（代理人）[^\\n|]{0,20}手写签名/.test(t)) {
    result.甲方签字 = '是';
  } else if (/甲方[^\\n|]{0,40}(?:未|无)[^\\n|]{0,10}(?:签字|签名)/.test(t)) {
    result.甲方签字 = '否';
  }

  // 身份证复印件
  if (/(?:身份证|身份证复印件)/.test(t)) {
    if (/(?:未|无|没有)[^\\n|]{0,10}(?:身份证)/.test(t)) {
      result.甲方身份证复印件 = '否';
    } else if (/(?:有|附|已)[^\\n|]{0,10}(?:身份证)/.test(t)) {
      result.甲方身份证复印件 = '是';
    }
  }

  return result;
}

function mergeParty(values) {
  if (values.some((v) => v === '是')) return '是';
  if (values.length > 0 && values.every((v) => v === '否')) return '否';
  return '不确定';
}

/**
 * 签字合同有效性判定
 * - 有甲方签字 + 甲方盖章=是 → 有效（新增：盖章即可，不要求身份证）
 * - 有甲方签字 + 甲方身份证复印件=是 → 有效（原逻辑保留）
 * - 有甲方签字，但盖章和身份证都不是「是」→ 无效签字合同
 */
function evaluateSignContract(甲方签字, 甲方身份证复印件, 甲方盖章) {
  if (甲方签字 === '是') {
    if (甲方盖章 === '是' || 甲方身份证复印件 === '是') {
      return '有效';
    }
    return '无效签字合同';
  }
  if (甲方签字 === '否') return '不适用';
  return '不确定';
}

const pageResults = [];
const stampPages = base.stamp_pages || prepItems[0]?.json?.stamp_pages || [];

for (let i = 0; i < doubaoItems.length; i += 1) {
  const prep = prepItems[i]?.json || {};
  const rawText = extractText(doubaoItems[i].json);
  let parsed = {
    甲方盖章: '不确定',
    乙方盖章: '不确定',
    甲方签字: '不确定',
    甲方身份证复印件: '不确定',
    说明: '',
  };

  const jsonData = parseStampJson(rawText);
  if (jsonData) {
    parsed = {
      甲方盖章: normalizeYesNo(jsonData['甲方盖章'] || jsonData.甲方盖章),
      乙方盖章: normalizeYesNo(jsonData['乙方盖章'] || jsonData.乙方盖章),
      甲方签字: normalizeYesNo(jsonData['甲方签字'] || jsonData.甲方签字),
      甲方身份证复印件: normalizeYesNo(jsonData['甲方身份证复印件'] || jsonData.甲方身份证复印件),
      说明: jsonData['说明'] || jsonData.说明 || '',
    };
  } else {
    parsed = inferFromText(rawText);
    parsed.说明 = '豆包返回自然语言，已规则推断';
  }

  pageResults.push({
    page: prep.stamp_page || stampPages[i] || i + 1,
    ...parsed,
  });
}

const 甲方盖章 = mergeParty(pageResults.map((r) => r.甲方盖章));
const 乙方盖章 = mergeParty(pageResults.map((r) => r.乙方盖章));
const 甲方签字 = mergeParty(pageResults.map((r) => r.甲方签字));
const 甲方身份证复印件 = mergeParty(pageResults.map((r) => r.甲方身份证复印件));

let 双方盖章 = '不确定';
if (甲方盖章 === '是' && 乙方盖章 === '是') 双方盖章 = '是';
else if (甲方盖章 === '否' || 乙方盖章 === '否') 双方盖章 = '否';

let 签字合同状态 = evaluateSignContract(甲方签字, 甲方身份证复印件, 甲方盖章);
if (pageResults.some((r) => evaluateSignContract(r.甲方签字, r.甲方身份证复印件, r.甲方盖章) === '无效签字合同')) {
  签字合同状态 = '无效签字合同';
}

const detail = pageResults
  .map(
    (r) =>
      `第${r.page}页：甲方盖章${r.甲方盖章}，乙方盖章${r.乙方盖章}，甲方签字${r.甲方签字}，身份证${r.甲方身份证复印件}${r.说明 ? `（${r.说明}）` : ''}`,
  )
  .join('；');

return {
  json: {
    record_id: base.record_id,
    execNo: base.execNo,
    活动名称: base.活动名称,
    活动日期: base.活动日期,
    活动人数: base.活动人数,
    活动总费用: base.活动总费用,
    付款比例和方式: base.付款比例和方式,
    付款比例是否预警: base.付款比例是否预警,
    字段识别说明: base.字段识别说明,
    双方盖章,
    甲方盖章,
    乙方盖章,
    甲方签字,
    甲方身份证复印件,
    签字合同状态,
    盖章说明: detail,
    签章页识别明细: pageResults,
  },
};

